public class Main {
    static final int MOD = 998244353;

    static int modPow(int a, int e) {
        int res = 1;
        while (e > 0) {
            if ((e & 1) == 1) res = (int) ((long) res * a % MOD);
            a = (int) ((long) a * a % MOD);
            e >>= 1;
        }
        return res;
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        int N = Integer.parseInt(br.readLine());
        int size = 1 << N;
        int[] A = new int[size];
        long sum = 0;
        StringTokenizer st = new StringTokenizer(br.readLine());
        for (int i = 0; i < size; i++) {
            A[i] = Integer.parseInt(st.nextToken());
            sum += A[i];
        }
        long invSum = modPow((int) (sum % MOD), MOD - 2);
        for (int i = 0; i < size; i++) {
            A[i] = (int) (A[i] * invSum % MOD);
        }

        // f[i] = expected steps starting from 0 to reach i
        // Use FWHT: transform A to get polynomial (1 - A_hat) invert etc.
        int[] B = new int[size];
        for (int i = 0; i < size; i++) B[i] = (MOD - A[i]) % MOD;
        B[0] = (B[0] + 1) % MOD; // 1 - A

        // FWHT (XOR convolution)
        for (int len = 1; len < size; len <<= 1) {
            for (int i = 0; i < size; i += len * 2) {
                for (int j = 0; j < len; j++) {
                    int u = B[i + j];
                    int v = B[i + j + len];
                    B[i + j] = (u + v) % MOD;
                    B[i + j + len] = (u - v + MOD) % MOD;
                }
            }
        }

        // B[k] = 1 - A_hat(k)
        // Solve: f_hat(k) * (1 - A_hat(k)) = 1 for k != 0, and f_hat(0)=0
        int[] fhat = new int[size];
        fhat[0] = 0;
        int invN = modPow(size, MOD - 2);
        for (int i = 1; i < size; i++) {
            fhat[i] = (int) ((long) invN * modPow(B[i], MOD - 2) % MOD);
        }

        // Inverse FWHT
        for (int len = 1; len < size; len <<= 1) {
            for (int i = 0; i < size; i += len * 2) {
                for (int j = 0; j < len; j++) {
                    int u = fhat[i + j];
                    int v = fhat[i + j + len];
                    fhat[i + j] = (u + v) % MOD;
                    fhat[i + j + len] = (u - v + MOD) % MOD;
                }
            }
        }
        for (int i = 0; i < size; i++) {
            fhat[i] = (int) ((long) fhat[i] * invN % MOD);
        }

        // fhat[i] is expected steps from 0 to i
        // We need expected steps until X becomes i (starting from 0)
        // That's exactly fhat[i]
        for (int i = 0; i < size; i++) {
            System.out.println(fhat[i]);
        }
    }
}

