public class Main {
    static final long MOD = 998244353;
    static long inv(long a) { return pow(a, MOD-2); }
    static long pow(long a, long b) { long r=1; a%=MOD; for(;b>0;b>>=1){if((b&1)==1)r=r*a%MOD;a=a*a%MOD;} return r; }
    static void wht(long[] a, boolean inv2) {
        int n=a.length;
        for(int len=1;len<n;len<<=1)
            for(int i=0;i<n;i+=len<<1)
                for(int j=0;j<len;j++){long u=a[i+j],v=a[i+j+len];a[i+j]=(u+v)%MOD;a[i+j+len]=(u-v+MOD)%MOD;}
        if(inv2){long ni=inv(n);for(int i=0;i<n;i++)a[i]=a[i]*ni%MOD;}
    }
    public static void main(String[] args) throws Exception {
        BufferedReader br=new BufferedReader(new InputStreamReader(System.in));
        int N=Integer.parseInt(br.readLine().trim());
        int sz=1<<N;
        long[] p=new long[sz];
        StringTokenizer st=new StringTokenizer(br.readLine());
        long Q=Long.parseLong(st.nextToken());
        long invQ=inv(Q);
        for(int i=0;i<sz;i++){long pi=Long.parseLong(st.nextToken());p[i]=pi*invQ%MOD;}
        wht(p,false);
        // F̂[k] = R̂[k]/(1-p̂[k]) for k!=0, F̂[0] free
        // R̂[k] = sum_{y!=0} (-1)^{popcount(y&k)}
        // For k!=0: R̂[k] = -1 (since sum_{all y} (-1)^{...} = 0, so sum_{y!=0} = -1)
        // For k=0: R̂[0] = sz-1
        long[] Fhat=new long[sz];
        long sumRest=0;
        for(int k=1;k<sz;k++){
            long denom=(1-p[k]+MOD)%MOD;
            Fhat[k]=(MOD-1)*inv(denom)%MOD; // -1/denom
            sumRest=(sumRest+Fhat[k])%MOD;
        }
        Fhat[0]=(MOD-sumRest)%MOD;
        wht(Fhat,true);
        StringBuilder sb=new StringBuilder();
        for(int i=0;i<sz;i++){sb.append(Fhat[i]);if(i<sz-1)sb.append('\n');}
        System.out.println(sb);
    }
}

