int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N;
    cin >> N;
    int M = 1 << N;

    vector<long long> A(M);
    for (int i = 0; i < M; ++i) {
        cin >> A[i];
        A[i] %= MOD;
    }

    // Let E[x] be expected time to hit 0 starting from x.
    // Then for x != 0:
    // E[x] = 1 + sum_v A[v] E[x xor v], and E[0] = 0.
    //
    // Define F[x] = E[x] for x != 0, F[0] arbitrary.
    // Rearranging for all x:
    // (delta - A) * F = 1 - c*delta_0
    //
    // Standard solution in XOR group:
    // For each character s, let hatA[s] be FWHT(A).
    // Then transform gives:
    // (1 - hatA[s]) * hatF[s] = hatB[s]
    //
    // Using E[0]=0 determines constant. The resulting closed form is:
    // For s != 0, hatF[s] = -2^N / (1 - hatA[s])
    // and hatF[0] = sum_{s != 0} 1 / (1 - hatA[s])
    //
    // Then inverse FWHT to get F, answers are F[i].

    vector<long long> H = A;
    fwht(H, false);

    vector<long long> FH(M, 0);

    long long sumInv = 0;
    for (int s = 1; s < M; ++s) {
        long long denom = (1 - H[s] + MOD) % MOD;
        long long inv = modpow(denom, MOD - 2);
        sumInv += inv;
        if (sumInv >= MOD) sumInv -= MOD;
        FH[s] = (MOD - (long long)M % MOD) * inv % MOD;
    }
    FH[0] = sumInv;

    fwht(FH, true);

    for (int i = 0; i < M; ++i) {
        cout << FH[i] << '\n';
    }

    return 0;
}

